DO $$
DECLARE org bigint;un bigint;oc bigint;f bigint;foreign_f bigint;name_id bigint;surname_id bigint;hidden_id bigint;foreign_id bigint;
 actor uuid:=gen_random_uuid();oid bigint;tid bigint;second_ticket bigint;empty_ticket bigint;w uuid;reply jsonb;token text:=repeat('c',64);offer_token text:=repeat('d',64);
BEGIN
 INSERT INTO public.organizations(title) VALUES('Waitlist context labels') RETURNING id INTO org;
 INSERT INTO public.units(title,organization) VALUES('Labels',org) RETURNING id INTO un;
 INSERT INTO public.occasions(title,unit,organization,link,start_time,end_time) VALUES('Visible event title',un,org,gen_random_uuid()::text,now(),now()+interval '1 day') RETURNING id INTO oc;
 INSERT INTO public.forms(occasion,link) VALUES(oc,gen_random_uuid()::text) RETURNING id INTO f;
 INSERT INTO public.forms(occasion,link) VALUES(oc,gen_random_uuid()::text) RETURNING id INTO foreign_f;
 INSERT INTO public.form_fields(form,type,is_ticket_field) VALUES(f,'name',true) RETURNING id INTO name_id;
 INSERT INTO public.form_fields(form,type,is_ticket_field) VALUES(f,'surname',true) RETURNING id INTO surname_id;
 INSERT INTO public.form_fields(form,type,is_ticket_field,is_hidden) VALUES(f,'name',true,true) RETURNING id INTO hidden_id;
 INSERT INTO public.form_fields(form,type,is_ticket_field) VALUES(foreign_f,'name',true) RETURNING id INTO foreign_id;
 INSERT INTO eshop.orders(occasion,form,state,order_sequence,order_symbol,data) VALUES(oc,f,'waitlisted',public.next_order_sequence(oc),public.generate_order_symbol(),'{"name":"Shared","surname":"Contact"}') RETURNING id INTO oid;
 INSERT INTO eshop.tickets(occasion,state,data) VALUES(oc,'waitlisted',jsonb_build_object('fields',jsonb_build_array(jsonb_build_object(name_id::text,'Ada'),jsonb_build_object(surname_id::text,'Lovelace'),jsonb_build_object(hidden_id::text,'Hidden'),jsonb_build_object(foreign_id::text,'Foreign')))) RETURNING id INTO tid;
 INSERT INTO eshop.order_product_ticket("order",ticket) VALUES(oid,tid);
 INSERT INTO eshop.waitlist_capabilities(token_hash,organization_id,form_id,order_id,kind) VALUES(encode(extensions.digest(token,'sha256'),'hex'),org,f,oid,'manage');
 PERFORM set_config('request.jwt.claim.sub','',true);
 reply:=public.get_waitlist_offer_form(token,NULL,oid);
 ASSERT (reply->>'code')::int=200,'Authorized management context rejected';
 ASSERT reply->>'occasionTitle'='Visible event title','Occasion context missing';
 ASSERT reply->>'orderSymbol'=(SELECT order_symbol FROM eshop.orders WHERE id=oid),'Order symbol missing';
 ASSERT reply#>>'{tickets,0,displayName}'='Ada Lovelace','Visible scoped ticket name not projected';
 ASSERT (public.get_form_by_link((SELECT link FROM public.forms WHERE id=f))::jsonb)#>>'{data,occasion,title}'='Visible event title','Initial public form lacks occasion title';
 INSERT INTO eshop.tickets(occasion,state,data) VALUES(oc,'waitlisted',jsonb_build_object('fields',jsonb_build_array(jsonb_build_object(name_id::text,'Alan'),jsonb_build_object(surname_id::text,'Turing')))) RETURNING id INTO second_ticket;
 INSERT INTO eshop.tickets(occasion,state,data) VALUES(oc,'waitlisted','{"fields":[]}') RETURNING id INTO empty_ticket;
 INSERT INTO eshop.order_product_ticket("order",ticket) VALUES(oid,second_ticket),(oid,empty_ticket);
 reply:=public.get_waitlist_offer_form(token,NULL,oid);
 ASSERT (SELECT value->>'displayName' FROM jsonb_array_elements(reply->'tickets') WHERE (value->>'id')::bigint=second_ticket)='Alan Turing','Group names merged';
 ASSERT (SELECT value->>'displayName' FROM jsonb_array_elements(reply->'tickets') WHERE (value->>'id')::bigint=empty_ticket) IS NULL,'Buyer name copied onto unnamed group ticket';
 ASSERT NOT EXISTS(SELECT 1 FROM jsonb_array_elements(reply->'tickets') WHERE value->>'displayName'='Shared Contact'),'Group tickets relabeled as buyer';
 ASSERT public.get_waitlist_ticket_display_name_internal(f,'{"fields":[]}','{"name":"Shared","surname":"Contact"}')='Shared Contact','Contact fallback missing';
 reply:=public.get_waitlist_offer_form(repeat('e',64),NULL,oid);
 ASSERT (reply->>'code')::int=403 AND NOT reply ? 'occasionTitle' AND NOT reply ? 'orderSymbol','Invalid capability leaked context';
 INSERT INTO eshop.waitlist_offers(order_id,form_id,created_at,expires_at,revision) VALUES(oid,f,now()-interval '1 day',now()+interval '1 hour',1) RETURNING id INTO w;
 INSERT INTO eshop.waitlist_offer_slots(offer_id,ticket_id,form_id) VALUES(w,tid,f);
 INSERT INTO eshop.waitlist_capabilities(token_hash,organization_id,form_id,order_id,offer_id,kind,expires_at) VALUES(encode(extensions.digest(offer_token,'sha256'),'hex'),org,f,oid,w,'offer',now()+interval '1 hour');
 UPDATE eshop.waitlist_offers SET expires_at=now()-interval '1 second' WHERE id=w;
 reply:=public.get_waitlist_offer_form(offer_token,w,NULL);
 ASSERT (reply->>'code')::int=200 AND reply->'form'='null'::jsonb,'Expired offer terminal unavailable';
 ASSERT reply->>'occasionTitle'='Visible event title','Terminal occasion context missing';
 ASSERT reply->>'orderSymbol'=(SELECT order_symbol FROM eshop.orders WHERE id=oid),'Terminal order context missing';
 ASSERT NOT reply ? 'orderData','Terminal answers leaked';
 ASSERT reply->'tickets'='[]'::jsonb,'Terminal ticket data leaked';
 INSERT INTO auth.users(id,email) VALUES(actor,actor::text||'@example.invalid');
 INSERT INTO public.user_info(id,email_readonly) VALUES(actor,actor::text||'@example.invalid');
 INSERT INTO public.occasion_users(occasion,"user",is_editor_order_view) VALUES(oc,actor,true);
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 reply:=public.get_waitlist_order_detail(oid);
 ASSERT reply->>'occasionTitle'='Visible event title','Admin occasion context missing';
 ASSERT reply#>>'{tickets,0,displayName}'='Ada Lovelace','Admin label missing';
 ASSERT NOT EXISTS(SELECT 1 FROM jsonb_array_elements(reply->'tickets') WHERE value->>'displayName'='Shared Contact'),'Admin group tickets relabeled as buyer';
 ASSERT reply#>>'{tickets,0,createdAt}' IS NOT NULL,'Actual ticket timestamp missing';
END $$;
